import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0015: Why the Core Maintains an Internal Toolbox, Plugins Are the Rule Layer","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0015-internal-toolbox-plugin-rule-layer.md","filePath":"adr/ADR-0015-internal-toolbox-plugin-rule-layer.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0015-internal-toolbox-plugin-rule-layer.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0015-why-the-core-maintains-an-internal-toolbox-plugins-are-the-rule-layer" tabindex="-1">ADR-0015: Why the Core Maintains an Internal Toolbox, Plugins Are the Rule Layer <a class="header-anchor" href="#adr-0015-why-the-core-maintains-an-internal-toolbox-plugins-are-the-rule-layer" aria-label="Permalink to “ADR-0015: Why the Core Maintains an Internal Toolbox, Plugins Are the Rule Layer”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: adr-principles.md §17.15, ADR-0002, ADR-0012</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Probes and recovery actions cover HTTP, RPC, SSH, service control and other transports/protocols. If every plugin implements its own transport, security hardening (TLS verification, SSRF protection, SSH host-key verification, timeout/retry/cancellation, credential-safe reads) is diluted across N implementations and cannot be uniformly enforced.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The core converges a set of &quot;internal integration tools&quot; as capability executors (HTTP client, RPC client, SSH client, process/service/disk/network-connectivity probes, controlled command execution, reboot control), declared via Capability + OperationParams. Plugins and built-in capabilities share one dispatch table: built-in capabilities execute in-process in the core; plugin-declared capabilities execute in the plugin subprocess. Plugins no longer implement transports themselves — they provide capability declarations and rule logic (targets, parameters, decisions, verification).</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Self-contained plugins, each implementing its own transport</strong>: duplicated implementations; hardening easily bypassed (one plugin disabling TLS verification); larger plugin footprint and attack surface.</li><li><strong>Built-in only (no plugins)</strong>: scenario-specific logic (mihomo/OpenClash domain decisions) cannot be contributed by the community.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: transport hardening happens once in one place (the webhook&#39;s SSRF protection is the first instance); timeout/cancel/budget/audit semantics are unified; plugins are thinner and auditable. Cons: the core&#39;s tool surface must be continuously maintained; plugin freedom shrinks (no arbitrary custom protocols) — new protocol needs mean adding a core tool first, then writing plugin-layer rules.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>P2 platform adapters (systemd/launchd/SCM, network interface/route/DNS) register as tool executors in the same registry.</li><li>The Webhook notification channel reuses the toolbox&#39;s HTTP client semantics (including SSRF policy, implemented).</li><li>Python outbound bindings expose tool calls, not arbitrary code execution.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};